const parseDate=v=>{if(v instanceof Date&&!isNaN(+v))return v;if(typeof v==='number')return new Date(Date.UTC(1899,11,30)+Math.floor(v)*86400000+(v%1)*86400000);const s=String(v??'').trim(),m=s.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})(.*)$/);if(m){const d=new Date(+m[3],+m[2]-1,+m[1]);if(d.getDate()!==+m[1]||d.getMonth()!==+m[2]-1)return null;const tail=m[4].trim();if(tail){const t=tail.match(/(\d{1,2}):(\d{2})(?::(\d{2}))?/);if(t)d.setHours(+t[1],+t[2],+(t[3]||0))}return d}const d=new Date(s);return isNaN(+d)?null:d};
