function parseMatrixRows(matrix,rules,source='statement'){const out=[];const headersAt=matrix.findIndex(row=>{const h=row.map(norm);return h.some(x=>/^(date|transaction date|date time|date and time)$/.test(x)||x.includes('date'))&&h.some(x=>x==='amount'||x.includes('amount'))&&h.some(x=>/transaction details|description|particular|narration|remarks|merchant|payee|details/.test(x))});if(headersAt<0)return out;const headers=matrix[headersAt].map(x=>String(x||'').trim()),key=(...terms)=>headers.findIndex(h=>terms.some(t=>norm(h)===norm(t)||norm(h).includes(norm(t)))),value=(row,...terms)=>{const i=key(...terms);return i<0?'':row[i]};for(const row of matrix.slice(headersAt+1)){const desc=String(value(row,'transaction details','description','particulars','particular','narration','remarks','merchant','payee','details')).trim();const rawAmount=String(value(row,'amount','transaction amount','paid amount','received amount')).replace(/[₹,\\s]/g,'');let amount=Number(rawAmount);if(!desc||!Number.isFinite(amount)||amount===0)continue;const dateValue=value(row,'date & time','date and time','transaction date','transaction datetime','timestamp','date');const d=parseDate(dateValue);if(!d)continue;const time=value(row,'time','transaction time');if(time){const tm=String(time).match(/(\\d{1,2}):(\\d{2})(?::(\\d{2}))?\\s*(am|pm)?/i);if(tm){let hh=+tm[1];if(tm[4])hh=hh%12+(tm[4].toLowerCase()==='pm'?12:0);d.setHours(hh,+tm[2],+(tm[3]||0),0)}}const direction=norm([value(row,'transaction type','type','direction','dr cr','debit credit','transaction direction'),value(row,'credit/debit','debit/credit','transaction mode')].join(' '));const text=norm(desc+' '+direction),self=/transferred to self|self transfer|between own accounts|own account transfer/.test(text),credit=/credit|received|refund|cashback|reversal credit/.test(direction)||/received from|money received|cashback|refund received/.test(text),debit=/debit|paid|sent/.test(direction)||/paid to|money sent|sent to|payment to/.test(text);if(/cr\\b/.test(direction))amount=Math.abs(amount);else if(/dr\\b/.test(direction))amount=-Math.abs(amount);else if(credit)amount=Math.abs(amount);else if(debit)amount=-Math.abs(amount);const type=self?'transfer':amount>0?'income':'expense';const ref=String(value(row,'upi ref no','upi ref','upi reference','utr','reference no','reference number','transaction id','txn id','transaction reference')||'').trim();const tag=String(value(row,'tags','tag','category')||'').trim();const rule=rules.find(r=>norm(desc).includes(norm(r.match)));const excluded=/money blocked|money unblocked|ipo|mandate setup|autopay setup|reversal initiated|failed transaction/.test(text);const name=desc.replace(/^(paid to|money sent to|sent to|received from|transferred to self|paid for|payment to)\\s*/i,'').trim();out.push({name:name||desc,amount:Math.abs(amount),category:rule?.category||guessCategory(name+' '+tag),method:'UPI',date:d.toISOString(),dateText:d.toLocaleString('en-IN'),notes:['Imported from '+source,ref?'UPI Ref: '+ref:'',tag?'Statement tag: '+tag:''].filter(Boolean).join(' · '),assignedTo:rule?.assignedTo||'',type,ref,excluded,reason:excluded?'Hold / failed transaction':self?'Self transfer':credit?'Incoming credit':'Review expense',selected:!excluded})}return out}
