async function parsePdf(file,rules,onProgress){const pdf=await getDocument({data:await file.arrayBuffer()}).promise,lines=[];for(let p=1;p<=pdf.numPages;p++){const page=await pdf.getPage(p),tc=await page.getTextContent(),items=tc.items.map(i=>({y:Math.round(i.transform[5]),x:i.transform[4],s:i.str})).sort((a,b)=>b.y-a.y||a.x-b.x);let ys=[];for(const it of items){let r=ys.find(x=>Math.abs(x.y-it.y)<3);if(!r)ys.push(r={y:it.y,a:[]});r.a.push(it)}lines.push(...ys.sort((a,b)=>b.y-a.y).map(r=>r.a.sort((a,b)=>a.x-b.x).map(x=>x.s).join(' ')));onProgress(Math.round(p/pdf.numPages*100))}const out=[];let cur=null,lastDate='';const flush=()=>{if(cur?.ref&&cur.amount){const text=norm(cur.description+' '+cur.note+' '+cur.tag),self=/transferred to self|self transfer|between own accounts|own account transfer/.test(text),excluded=/money blocked|money unblocked|ipo|mandate setup|autopay setup|reversal|refund received/.test(text),credit=/received from|money received/.test(text),rule=rules.find(r=>norm(cur.description).includes(norm(r.match)));const name=cur.description.replace(/^(paid to|money sent to|received from|transferred to self)\s*/i,'').trim();out.push({...cur,name,amount:Math.abs(cur.amount),type:self?'transfer':credit?'income':'expense',category:rule?.category||guessCategory(name+' '+cur.tag),assignedTo:rule?.assignedTo||'',method:'UPI',notes:['Imported from statement','UPI Ref: '+cur.ref].join(' · '),excluded,selected:!excluded})}cur=null};for(const line of lines){const dm=line.match(/^(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s*('?\d{2,4})?\s*(.*)$/i);if(dm){flush();const yr=dm[3]?(dm[3].replace("'","").length===2?'20'+dm[3].replace("'",""):dm[3].replace("'","")):String(new Date().getFullYear());const d=new Date(yr+' '+dm[2]+' '+dm[1]);lastDate=d.toISOString();cur={date:lastDate,dateText:d.toLocaleDateString('en-IN'),description:dm[4]||'',amount:null,ref:'',tag:'',note:''};continue}if(!cur)continue;const ref=line.match(/(?:UPI\s*Ref(?:erence)?\s*(?:No\.?|ID)?|UTR)\s*[:#-]?\s*(\d{8,})/i);if(ref)cur.ref=ref[1];const amt=line.match(/[+-]\s*Rs\.?\s*([\d,]+(?:\.\d{1,2})?)/i);if(amt)cur.amount=Number(amt[1].replace(/,/g,''));if(/^#/.test(line))cur.tag=line.replace(/^#\s*/,'');if(/Note:/i.test(line))cur.note+=' '+line;if(/^(Paid to|Money sent to|Received from|Transferred to Self|Paid for)/i.test(line))cur.description+=' '+line}flush();return out}
