 const importFile=async e=>{const file=e.target.files?.[0];if(!file)return;setFileName(file.name);setPreview([]);setProgress(1);try{let found;if(/\.pdf$/i.test(file.name))found=await parsePdf(file,rules,setProgress);else if(/\.csv$/i.test(file.name)){const txt=await file.text(),parsed=Papa.parse(txt,{header:false,skipEmptyLines:true}).data,provider=upiProvider==='auto'?(/phonepe/i.test(file.name)?'PhonePe':/paytm/i.test(file.name)?'Paytm':/google|gpay/i.test(file.name)?'Google Pay':'UPI app'):upiProvider;found=parseMatrixRows(parsed,rules,provider)}else{const x=await import('xlsx');const wb=x.read(await file.arrayBuffer(),{type:'array',cellDates:true});found=parseRowsFromSheet(wb,rules)}if(!found.length)throw Error('I could not identify the transaction table. Please choose the original CSV/Excel statement exported by your UPI app; supported columns include Date, Amount, Description/Transaction Details and Debit/Credit or Transaction Type.');const existing=new Map();rows.forEach(x=>{const m=(x.notes||'').match(/UPI Ref:\s*([^ ·]+)/i);if(m)existing.set(m[1],x)});found.forEach(x=>{const prior=x.ref?existing.get(x.ref):null;x.existingId=prior?.id||'';x.duplicate=!!prior&&/\[POCKET_TYPE:(income|transfer)\]/i.test(prior.notes||'');if(x.duplicate)x.selected=false});setPreview(found);setProgress(100);say(found.length+' statement rows ready for review')}catch(e){say('Import failed: '+e.message)}finally{e.target.value=''}};
