 const activeInv=investments.filter(x=>!['sold','matured'].includes(x.status)),invested=sum(activeInv.map(x=>({amount:x.investedAmount}))),current=sum(activeInv.map(x=>({amount:x.currentValue}))),invGain=current-invested;
 if(loading)return <div className="loading">Pocket<small>Loading your workspace…</small></div>;
 if(!user)return <main className="auth"><form className="authbox" onSubmit={authSubmit}><div className="brand"><span className="brand-mark" aria-hidden="true"><svg viewBox="0 0 40 40" fill="none"><rect x="5" y="5" width="30" height="30" rx="10" stroke="currentColor" strokeWidth="2.2"/><path d="M14 27V13h7.5a5 5 0 0 1 0 10H14" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"/><circle cx="27.5" cy="27" r="2.2" fill="currentColor"/></svg></span><span className="brand-word">pocket</span></div><span className="eyebrow">YOUR MONEY, IN ONE PLACE</span><h1>{mode==='login'?'Welcome back':'Create your account'}</h1><p className="muted">A calmer way to understand where your money goes.</p>{mode==='signup'&&<input placeholder="Your name" required value={auth.name} onChange={e=>setAuth({...auth,name:e.target.value})}/>}<input type="email" placeholder="Email address" required value={auth.email} onChange={e=>setAuth({...auth,email:e.target.value})}/><input type="password" placeholder="Password" minLength="8" required value={auth.password} onChange={e=>setAuth({...auth,password:e.target.value})}/>{err&&<p className="error">{err}</p>}<button className="btn primary" disabled={busy}>{busy?'Please wait…':mode==='login'?'Sign in':'Create account'}</button><p className="switch">{mode==='login'?'New to Pocket?':'Already have an account?'} <button type="button" onClick={()=>setMode(mode==='login'?'signup':'login')}>{mode==='login'?'Create account':'Sign in'}</button></p><small>Your data stays in your Appwrite account.</small></form></main>;
