 {typeFilter==='income'&&<><div className="income-summary"><article><small>Income in this view</small><b>{cash(incomeTotal)}</b><span>{incomeFiltered.length} incoming records</span></article><article><small>Average received</small><b>{cash(incomeFiltered.length?incomeTotal/incomeFiltered.length:0)}</b><span>Per incoming transaction</span></article><article><small>Unique people / sources</small><b>{incomeSources.length}</b><span>Based on “Received from / payer”</span></article></div><section className="income-sources"><div className="panelhead"><div><h3>Who paid you?</h3><small>Income grouped by the person or source recorded on each transaction.</small></div></div>{incomeSources.length?<div className="source-list">{incomeSources.map(x=><div className="source-row" key={x.name}><div><b>{x.name}</b><small>{x.count} payment{x.count===1?'':'s'}</small></div><strong>{cash(x.total)}</strong></div>)}</div>:<div className="empty">No income matches these filters yet. Add a payer when recording income.</div>}</section></>}
